import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";

import { OutlineButton } from "../components/button/Button";
import HeroSlide from "../components/hero-slide/HeroSlide";
import MovieList from "../components/movie-list/MovieList";

import tmdbApi, { category } from "../api/tmdbApi";
import * as Config from "./../constants/Config";

// Import your exact MovieLens top 10 dataset JSON file
import customGenreData from "../components/movie-grid/top10_movies_by_genre.json";

const Home = () => {
  const actionMovies = customGenreData["action"] || [];
  const dramaMovies = customGenreData["drama"] || [];
  const animationMovies = customGenreData["animation"] || [];
  const topRatedOverall = customGenreData["drama"] || [];

  const [recommendedMovies, setRecommendedMovies] = useState([]);
  const [loadingRecs, setLoadingRecs] = useState(false);

  // Read current user & watchlist from localStorage (matches typical app setup; swap if using a context hook)
  const currentUser = React.useMemo(() => {
    try {
      return JSON.parse(localStorage.getItem("currentUser") || "null");
    } catch {
      return null;
    }
  }, []);

  const watchlist = currentUser?.watchlist || [];
  const watchedMovies = watchlist.filter((m) => m.status === "watched");

  useEffect(() => {
    let isMounted = true;

    const loadHomeRecommendations = async () => {
      // Fallback for signed-out users or users with no watched movies yet
      if (!currentUser || watchedMovies.length === 0) {
        if (isMounted) {
          setRecommendedMovies(topRatedOverall.slice(0, 10));
        }
        return;
      }

      setLoadingRecs(true);
      try {
        const res = await fetch(`${process.env.PUBLIC_URL || ""}/recommendations.json`);
        const jsonRecs = res.ok ? await res.json() : [];

        const svdScoreMap = new Map();
        jsonRecs.forEach((item) => {
          svdScoreMap.set(String(item.movieId), Number(item.predictedRating) || 0);
        });

        const excludedIds = new Set(watchlist.map((m) => String(m.id)));
        const genreCounts = {};
        const candidates = new Map();

        await Promise.all(
          watchedMovies.map(async (w) => {
            try {
              const detail = await tmdbApi.detail(category.movie, w.id, { params: {} });
              (detail.genres || []).forEach((g) => {
                const gid = String(g.id);
                genreCounts[gid] = (genreCounts[gid] || 0) + 1;
              });
            } catch {}

            try {
              const simRes = await tmdbApi.similar(category.movie, w.id, { params: { page: 1 } });
              (simRes?.results || []).slice(0, 10).forEach((m) => {
                const mid = String(m.id);
                if (!excludedIds.has(mid) && !candidates.has(mid)) {
                  candidates.set(mid, m);
                }
              });
            } catch {}
          })
        );

        const topSvdIds = jsonRecs
          .map((item) => String(item.movieId))
          .filter((id) => !excludedIds.has(id) && !candidates.has(id))
          .slice(0, 15);

        const svdDetails = await Promise.all(
          topSvdIds.map(async (id) => {
            try {
              return await tmdbApi.detail(category.movie, id, { params: {} });
            } catch {
              return null;
            }
          })
        );

        svdDetails.filter(Boolean).forEach((m) => {
          candidates.set(String(m.id), m);
        });

        const ranked = Array.from(candidates.values())
          .map((m) => {
            const movieGenreIds = m.genre_ids
              ? m.genre_ids.map(String)
              : (m.genres || []).map((g) => String(g.id));

            const genreScore = movieGenreIds.reduce(
              (sum, gid) => sum + (genreCounts[gid] || 0) * 1.2,
              0
            );
            const svdScore = svdScoreMap.get(String(m.id)) || 3.5;

            return {
              ...m,
              finalScore: svdScore + genreScore,
            };
          })
          .sort((a, b) => b.finalScore - a.finalScore)
          .slice(0, 10);

        if (isMounted) {
          setRecommendedMovies(ranked.length > 0 ? ranked : topRatedOverall.slice(0, 10));
        }
      } catch (err) {
        console.error("Error loading home recommendations:", err);
        if (isMounted) {
          setRecommendedMovies(topRatedOverall.slice(0, 10));
        }
      } finally {
        if (isMounted) {
          setLoadingRecs(false);
        }
      }
    };

    loadHomeRecommendations();
    return () => {
      isMounted = false;
    };
  }, [currentUser, JSON.stringify(watchlist)]);

  return (
    <>
      <HeroSlide />

      <div className="container">
        {/* --- WATCHLIST BANNER START --- */}
        <div className="section mb-3" style={{ marginTop: "20px" }}>
          <div
            style={{
              background: "linear-gradient(45deg, #1f1f1f, #333)",
              padding: "30px",
              borderRadius: "10px",
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
            }}
          >
            <div>
              <h2 style={{ margin: 0 }}>Your Personal Watchlist</h2>
              <p style={{ color: "#aaa", marginTop: "5px" }}>
                Keep track of what you want to watch and what you&apos;ve finished.
              </p>
            </div>
            <Link to={`/${Config.HOME_PAGE}/watchlist`}>
              <OutlineButton>View My Watchlist</OutlineButton>
            </Link>
          </div>
        </div>
        {/* --- WATCHLIST BANNER END --- */}

        {/* --- RECOMMENDED FOR YOU START --- */}
        <div className="section mb-3">
          <div className="section__header mb-2">
            <h2>
              {currentUser && watchedMovies.length > 0
                ? "Recommended For You"
                : "Recommended Top Picks"}
            </h2>
            <Link to={`/${Config.HOME_PAGE}/watchlist`}>
              <OutlineButton className="small">My Watchlist</OutlineButton>
            </Link>
          </div>
          {loadingRecs ? (
            <p style={{ color: "#aaa" }}>Loading recommendations...</p>
          ) : (
            <MovieList category={category.movie} type="custom" movies={recommendedMovies} />
          )}
        </div>
        {/* --- RECOMMENDED FOR YOU END --- */}

        {/* Section 1: Top Rated Movies */}
        <div className="section mb-3">
          <div className="section__header mb-2">
            <h2>Top Rated Movies</h2>
            <Link to={`/${Config.HOME_PAGE}/movie/genre/drama`}>
              <OutlineButton className="small">View more</OutlineButton>
            </Link>
          </div>
          <MovieList category={category.movie} type="custom" movies={topRatedOverall} />
        </div>

        {/* Section 2: Top Rated Action Movies */}
        <div className="section mb-3">
          <div className="section__header mb-2">
            <h2>Top Rated Action Movies</h2>
            <Link to={`/${Config.HOME_PAGE}/movie/genre/action`}>
              <OutlineButton className="small">View more</OutlineButton>
            </Link>
          </div>
          <MovieList category={category.movie} type="custom" movies={actionMovies} />
        </div>

        {/* Section 3: Top Rated Drama Movies */}
        <div className="section mb-3">
          <div className="section__header mb-2">
            <h2>Top Rated Drama Movies</h2>
            <Link to={`/${Config.HOME_PAGE}/movie/genre/drama`}>
              <OutlineButton className="small">View more</OutlineButton>
            </Link>
          </div>
          <MovieList category={category.movie} type="custom" movies={dramaMovies} />
        </div>

        {/* Section 4: Top Rated Animation */}
        <div className="section mb-3">
          <div className="section__header mb-2">
            <h2>Top Rated Animation</h2>
            <Link to={`/${Config.HOME_PAGE}/movie/genre/animation`}>
              <OutlineButton className="small">View more</OutlineButton>
            </Link>
          </div>
          <MovieList category={category.movie} type="custom" movies={animationMovies} />
        </div>
      </div>
    </>
  );
};

export default Home;
